    color: #050505;
    font-size: 26px;
    font-weight: 900;
}

.server-banner-card {
    grid-template-columns: 150px minmax(0, 1fr);
}

.server-banner-preview {
    width: 150px;
    min-height: 88px;
    border-radius: 16px;
    background:
        radial-gradient(circle at 20% 20%, rgba(var(--accent-rgb), .36), transparent 28%),
        linear-gradient(135deg, rgba(255,255,255,.12), rgba(255,255,255,.04));
    color: var(--text);
    font-size: 16px;
    font-weight: 900;
    letter-spacing: .08em;
}

.server-asset-copy {
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
}

.server-asset-title {
    color: var(--text);
    font-weight: 900;
    font-size: 13px;
}

.server-asset-sub {
    color: var(--text2);
    font-size: 11px;
    line-height: 1.5;
}

.server-asset-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.server-link-card {
    display: grid;
    gap: 10px;
    padding: 14px;
    border: 1px solid var(--border);
    border-radius: 18px;
    background:
        linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.015)),
        rgba(255,255,255,.02);
}

.server-link-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    gap: 8px;
    align-items: center;
}

.server-discover-head-actions {
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.server-discover-toolbar {
    display: grid;
    gap: 8px;
}

.server-discover-list {
    display: grid;
    gap: 10px;
    min-height: 200px;
    flex: 1;
    max-height: none;
