        MOBILE_NAV_PROGRESS: "MOBILE_NAV_PROGRESS",
        NETWORK_CONFIG: "NETWORK_CONFIG",
        PERSIST_DEVICE_IDENTITY: "PERSIST_DEVICE_IDENTITY",
        REFRESH_HISTORY: "REFRESH_HISTORY",
        REMOVE_CONTACT_REQUEST: "REMOVE_CONTACT_REQUEST",
